-- Stock module (stock.db)
-- Catalogue items and every movement in or out.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE inventory_items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                sku TEXT NOT NULL UNIQUE,
                name TEXT NOT NULL,
                category TEXT NOT NULL,
                unit TEXT NOT NULL,
                quantity REAL NOT NULL DEFAULT 0 CHECK (quantity >= 0),
                min_stock REAL NOT NULL DEFAULT 0 CHECK (min_stock >= 0),
                unit_cost REAL NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
                supplier TEXT DEFAULT '',
                location TEXT DEFAULT '',
                active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            , updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE stock_movements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_id INTEGER NOT NULL,
                movement_type TEXT NOT NULL CHECK (movement_type IN ('IN', 'OUT')),
                quantity REAL NOT NULL CHECK (quantity > 0),
                reference_type TEXT NOT NULL DEFAULT 'Manual',
                reference_no TEXT DEFAULT '',
                notes TEXT DEFAULT '',
                created_by TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (item_id) REFERENCES inventory_items(id)
            );

CREATE INDEX idx_inventory_active
                ON inventory_items(active, quantity);
CREATE INDEX idx_stock_movements_item
                ON stock_movements(item_id, created_at);
